import{_ as t,o as a,c as o,a4 as d}from"./chunks/framework.CmuCl-jw.js";const u=JSON.parse('{"title":"REST APIs","description":"","frontmatter":{},"headers":[],"relativePath":"developers/apis.md","filePath":"developers/apis.md"}'),s={name:"developers/apis.md"};function i(r,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[d('<h1 id="rest-apis" tabindex="-1">REST APIs <a class="header-anchor" href="#rest-apis" aria-label="Permalink to “REST APIs”">​</a></h1><p>Every Arcsecond server — the cloud at <code>api.arcsecond.io</code> or your own <a href="/local/">Arcsecond.local</a> install — exposes the same <strong>RESTful</strong> API. The easiest way to talk to it is the <a href="/cli/api-basics">CLI / Python module</a>, but the endpoints are plain HTTP and fully browseable.</p><h2 id="api-base-url" tabindex="-1">API base URL <a class="header-anchor" href="#api-base-url" aria-label="Permalink to “API base URL”">​</a></h2><p>The base URL depends on which server you target:</p><ul><li><strong>Arcsecond.local</strong>: your install&#39;s own API server (the host and port you configured during <code>arcsecond setup</code>).</li><li><strong>Cloud</strong>: <code>https://api.arcsecond.io</code>, where each observatory is addressed by its <strong>subdomain</strong> — <code>https://api.arcsecond.io/&lt;subdomain&gt;/…</code>.</li></ul><p>The resource paths are identical in both cases:</p><table tabindex="0"><thead><tr><th>Resources</th><th>Endpoint</th></tr></thead><tbody><tr><td>Observing Sites</td><td><code>…/observingsites/[&lt;uuid:uuid&gt;/]</code></td></tr><tr><td>Telescopes</td><td><code>…/telescopes/[&lt;uuid:uuid&gt;/]</code></td></tr><tr><td>Night Logs</td><td><code>…/nightlogs/[&lt;uuid:uuid&gt;/]</code></td></tr><tr><td>Data Packages</td><td><code>…/datapackages/[&lt;uuid:uuid&gt;/]</code></td></tr><tr><td>Datasets</td><td><code>…/datasets/[&lt;uuid:uuid&gt;/]</code></td></tr><tr><td>Data Files</td><td><code>…/datafiles/[&lt;int:pk&gt;/]</code></td></tr></tbody></table><p>Apart from Data Files (see accepted formats below), all detail endpoints use (v4) UUIDs as identifiers.</p><h2 id="restful-and-browseable" tabindex="-1">RESTful and browseable <a class="header-anchor" href="#restful-and-browseable" aria-label="Permalink to “RESTful and browseable”">​</a></h2><p>All endpoints are <strong>RESTful</strong> and browseable — purely resource-centric, stateless endpoints with 1 URL = 1 resource, using HTTP verbs to convey meaning (note the trailing slash):</p><table tabindex="0"><thead><tr><th>HTTP Verb</th><th>Payload?</th><th>Endpoint</th><th>Result(s)</th></tr></thead><tbody><tr><td><code>GET</code></td><td></td><td><code>…/observingsites/</code></td><td>List all observing sites, including the UUIDs of associated Telescopes</td></tr><tr><td><code>GET</code></td><td></td><td><code>…/telescopes/&lt;uuid&gt;/</code></td><td>Get the details of a given telescope</td></tr><tr><td><code>POST</code></td><td>✔️</td><td><code>…/datasets/</code></td><td>Create a new dataset (<code>PUT</code>/<code>PATCH</code> are not allowed on list endpoints)</td></tr><tr><td><code>PATCH</code></td><td>✔️</td><td><code>…/datapackages/&lt;uuid&gt;/</code></td><td>Partially update a given data package</td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to “Authentication”">​</a></h2><p>Authenticate with one of your two <strong>personal keys</strong>, never with the session token you obtain at login (if that token leaks, you would no longer be able to log in to fix anything):</p><ul><li><code>api_key</code> — full access to your account,</li><li><code>upload_key</code> — a restricted scope, just enough to upload data.</li></ul><p>Both are available on your Profile page. Include one in a custom header on every request:</p><ul><li><code>&#39;X-Arcsecond-API-Authorization&#39; = &#39;Key &lt;api_key&gt;&#39;</code>, or</li><li><code>&#39;X-Arcsecond-API-Authorization&#39; = &#39;Key &lt;upload_key&gt;&#39;</code></li></ul><p>The <a href="/cli/api-basics">CLI</a> handles all of this for you once you have logged in.</p><h2 id="how-data-is-organised" tabindex="-1">How data is organised <a class="header-anchor" href="#how-data-is-organised" aria-label="Permalink to “How data is organised”">​</a></h2><p>Data files live inside <strong><a href="/apps/data/datasets">Datasets</a></strong>, which are simply containers of files. When you <a href="/cli/upload">upload from the CLI</a>, the files you send land in the dataset you target.</p><p>To each FITS or XISF data file, an Observation or a Calibration is attached. Depending on the observation date, those are grouped into <strong>Night Logs</strong>, which run from local noon to the next local noon.</p><h2 id="accepted-file-formats" tabindex="-1">Accepted file formats <a class="header-anchor" href="#accepted-file-formats" aria-label="Permalink to “Accepted file formats”">​</a></h2><p>Compressed files ending in <code>.zip</code>, <code>.gzip</code> and <code>.bzip2</code> are supported.</p><p>Any file (compressed or not) whose inferred content type is <code>FITS image data</code> or <code>xisf</code>, or whose inferred MIME type is <code>image/fits</code>, is treated as FITS (respectively XISF) and has its headers parsed. In practice you can upload files with the known FITS extensions <code>fits, fit, fts, ft, mt, imfits, imfit, uvfits, uvfit, pha, rmf, arf, rsp, pi</code>.</p>',23)])])}const f=t(s,[["render",i]]);export{u as __pageData,f as default};
